-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 20: Classes e métodos genéricos — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('8edb53a4-4bf9-5372-a6a8-ec5dd8773143', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Genéricos permitem principalmente:', '["Parametrizar código por tipos com verificação estática.","Criar uma classe-fonte por objeto manualmente.","Eliminar qualquer tipo.","Aceitar somente int.","Dispensar compilação."]'::jsonb, 0, 'A mesma definição pode atender a vários tipos de referência.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.2, páginas 691–692 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('643e30b9-5e14-5bc3-9ee4-c413d287aa52', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Qual forma declara um método genérico que devolve seu argumento?', '["`T identidade<T>(T x)` como sintaxe Java.","`generic identidade(T)`.","`<T> T identidade(T x)`.","`void<T> identidade(x)`.","`<T> identidade` sem parâmetros nem retorno."]'::jsonb, 2, 'A seção de parâmetros de tipo antecede o tipo de retorno.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.3, páginas 693–694 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('154686a9-e191-51a9-b162-31e3360ef971', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Um argumento de tipo como T pode ser diretamente int em `Caixa<int>`?', '["Somente quando T for final.","Sim, com import java.lang.","Somente em métodos static.","Não, deve-se usar tipo de referência como Integer.","Sim, sempre."]'::jsonb, 3, 'Primitivos não são argumentos de tipos genéricos Java SE 8.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.3, páginas 693–694 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6129bc62-b401-5752-b399-0bbb69b698d1', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'A eliminação de tipos, erasure, ocorre principalmente para:', '["Impedir uso de Object.","Apagar todos os casts do código-fonte sempre.","Criar classes diferentes para cada objeto em todo caso.","Traduzir genéricos preservando compatibilidade com o modelo de execução.","Substituir o coletor."]'::jsonb, 3, 'Tipos são verificados na compilação, com tradução conforme as regras de erasure.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.3, páginas 693–694 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dcaac827-6d4a-554f-8736-ebc5da08480e', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Difícil', 'Para T sem limite explícito, seu limite superior implícito é:', '["Number.","Integer.","String.","Object.","Runnable."]'::jsonb, 3, 'O parâmetro não garante operações específicas de um tipo mais restrito.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.3, páginas 693–694 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6b4a527d-566a-50f2-b25f-c258c82eb9e6', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Declarar `<T extends Number>` restringe T a:', '["Somente Object exato.","Apenas classes sem métodos.","Number ou seus subtipos apropriados.","Qualquer primitivo diretamente.","Somente String."]'::jsonb, 2, 'O limite permite usar operações disponíveis no tipo Number.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.4, páginas 695–696 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f1ef2fb4-8d5f-5166-8ee3-6a9e46c72e54', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Para usar compareTo em T com contrato apropriado, pode-se declarar limite como:', '["`T throws Comparable`.","`T implements int`.","`T final String`.","`T extends int`.","`T extends Comparable<T>`."]'::jsonb, 4, 'O limite expressa a capacidade de comparação usada pelo algoritmo genérico.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.4, páginas 695–696 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bc6a2c63-4c9f-57ee-b5d4-951fad6db933', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Métodos genéricos podem ser sobrecarregados?', '["Não.","Sim, respeitando assinaturas e regras de erasure.","Somente em interfaces sem métodos.","Sim, ignorando a eliminação de tipos.","Somente com retorno diferente."]'::jsonb, 1, 'Assinaturas distintas no fonte não podem colidir ilegalmente após a tradução.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.5, páginas 697 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('920c47fc-f3aa-5be3-a7c2-51d90a82f502', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Uma classe genérica Caixa<T> pode manter um campo:', '["De tipo T.","Sempre public e final.","Static T usando o T de instância diretamente.","Sem declaração de tipo.","De tipo int como argumento genérico obrigatório."]'::jsonb, 0, 'O parâmetro da classe tipa os membros de instância pertinentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.6, páginas 698–703 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('583ee5ce-2dd4-5075-b31c-600cc4393e89', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Dentro de Caixa<T>, criar `new T()` é permitido diretamente?', '["Sim, sempre.","Sim, por boxing.","Não.","Somente quando private.","Somente se T estiver em Object."]'::jsonb, 2, 'Não há garantia de construtor acessível nem informação de tipo suficiente para essa sintaxe.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.6, páginas 698–703 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d6c054d6-90fe-5636-90c2-4e602a63c089', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Difícil', 'Em uma classe genérica, um campo static pode usar diretamente o parâmetro T da classe?', '["Somente se final.","Sim, em Java SE 8.","Somente para referências.","Sim, sempre.","Não."]'::jsonb, 4, 'O campo de classe não pertence a uma parametrização de instância específica.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.6, páginas 698–703 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8c19d497-1f39-52ec-adba-bd7737662ed1', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Difícil', 'List<String> é subtipo de List<Object> apenas porque String é subtipo de Object?', '["Não.","Somente para ArrayList.","Sim, sempre.","Sim, se todos os elementos forem não nulos.","Somente se vazia."]'::jsonb, 0, 'A invariância evita inserções incompatíveis por uma referência mais ampla.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.6, páginas 698–703 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8965e5dc-2918-53a5-bbc5-dc78435cf42f', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Um tipo bruto como List, sem argumento de tipo, existe principalmente para:', '["Criar listas imutáveis.","Armazenar somente primitivos.","Eliminar todos os avisos.","Garantir mais segurança que List<String>.","Compatibilidade com código anterior aos genéricos."]'::jsonb, 4, 'Seu uso pode perder verificações e gerar operações não seguras.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.7, páginas 704–706 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('bc042c9b-0456-5c9f-889f-8f94c899c384', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Uma operação não verificada com tipos brutos pode adiar um problema para:', '["Uma nova compilação automática.","Uma falha de conversão em execução.","Uma SQLException sempre.","Um erro de impressão obrigatório.","Uma remoção pelo coletor."]'::jsonb, 1, 'A perda de verificação estática pode permitir valores incompatíveis na estrutura.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.7, páginas 704–706 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('93e46464-7079-5d97-8587-04d2423027ea', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'O curinga `? extends Number` permite tratar a origem como fornecedora de:', '["Somente Integer garantido.","Primitivos int diretamente.","Valores legíveis como Number.","Qualquer objeto para inserção.","Somente String."]'::jsonb, 2, 'O tipo exato é desconhecido, mas seu limite superior é Number.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.8, páginas 707–709 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('96e08d4d-497c-508c-9653-e4903136675c', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Difícil', 'Adicionar Integer a uma List<? extends Number> arbitrária é seguro e permitido normalmente?', '["Somente se a lista estiver vazia.","Somente se positivo.","Sim, porque não há tipos.","Não, o subtipo concreto pode ser outro.","Sim, Integer sempre cabe em qualquer subtipo de Number."]'::jsonb, 3, 'A lista pode ser, por exemplo, uma List<Double>.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.8, páginas 707–709 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('06ebf1ad-fc98-5012-9fda-8c16df282f91', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'List<? super Integer> permite inserir valores Integer?', '["Somente Double.","Somente null.","Somente String.","Não, nunca.","Sim."]'::jsonb, 4, 'O tipo desconhecido é um supertipo de Integer adequado ao recebimento desses valores.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.8, páginas 707–709 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dbce9ea0-8051-51b2-b540-bb1da54a9e8b', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Difícil', 'Ao ler uma List<? super Integer>, qual tipo geral é garantido sem cast adicional?', '["Object.","String.","Number sempre.","int.","Integer sempre."]'::jsonb, 0, 'O limite inferior ajuda na inserção, não garante Integer para todos os elementos já presentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.8, páginas 707–709 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8b9cd50d-f9f0-5dbc-9cd6-18f89047ba8e', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'List<?> representa:', '["Somente List<Object>.","Uma lista de um tipo de elemento desconhecido.","Uma lista de qualquer mistura livremente inserível.","Um tipo bruto sem verificação.","Uma lista necessariamente vazia."]'::jsonb, 1, 'O curinga mantém restrições de segurança mesmo sem nomear o tipo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.8, páginas 707–709 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('886a00bf-ab84-5253-beb2-78171b20ae61', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Para parâmetro T sem limite, qual declaração é válida para recebê-lo em uma variável de referência geral?', '["`Integer i = valorT;` sempre.","`Object o = valorT;`.","`int n = valorT;` sempre.","`String s = valorT;` sempre.","`Runnable r = valorT;` sempre."]'::jsonb, 1, 'Todo valor referenciável de T é compatível com seu limite superior Object.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 20, seção 20.3, páginas 693–694 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
